import "./DataTable.css";

export type Row = {
  id: string;
  cells: string[];
};

type DataTableProps = {
  rows: Row[];
  loading: boolean;
};

function PlaceholderRow(): JSX.Element {
  return (
    <tr>
      <td><span className="shimmer-cell" /></td>
      <td><span className="shimmer-cell" /></td>
      <td><span className="shimmer-cell" /></td>
    </tr>
  );
}

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const placeholders = [0, 1, 2, 3, 4];

  return (
    <table role="table" className="data-table">
      <tbody>
        {loading
          ? placeholders.map((i) => <PlaceholderRow key={i} />)
          : rows.map((row) => (
              <tr key={row.id}>
                {row.cells.map((cell, idx) => (
                  <td key={idx}>{cell}</td>
                ))}
              </tr>
            ))
        }
      </tbody>
    </table>
  );
}
